#!/usr/bin/env python3
from __future__ import annotations
import argparse,csv,json
from pathlib import Path
import pandas as pd
def main():
 p=argparse.ArgumentParser();p.add_argument('--jobs',type=Path,required=True);p.add_argument('--status',type=Path,required=True);p.add_argument('--merge-summary',type=Path,required=True);p.add_argument('--evaluation-lock',type=Path,required=True);p.add_argument('--rollouts',type=Path,required=True);p.add_argument('--output',type=Path,required=True);p.add_argument('--report',type=Path,required=True);a=p.parse_args();j=list(csv.DictReader(a.jobs.open(),delimiter='\t'));s=list(csv.DictReader(a.status.open(),delimiter='\t'));d=pd.read_csv(a.rollouts);lock=json.loads(a.evaluation_lock.read_text());key=['task_id','condition','method','policy_seed','rollout_index'];checks={'jobs_150':len(j)==150,'status_150_pass':len(s)==150 and all(x['status']=='PASS' for x in s),'rollouts_1500':len(d)==1500,'duplicates_zero':not d.duplicated(key).any(),'seeds_exact':set(d.policy_seed)=={20260912,20260913,20260914},'methods_exact':set(d.method)=={'linear_sarm_equiv','pathgraph_reward_v1_locked'},'paired_registry_present':lock.get('paired_evaluation') is True,'test_not_used':lock.get('test_used_for_selection') is False,'metrics_finite':bool(d[['success','recovery_success','failed','steps']].notna().all().all())};decision='REFINE1_FROZEN_EVALUATION_COMPLETE' if all(checks.values()) else ('EVALUATION_PAIRING_ERROR' if not checks['duplicates_zero'] else 'RETRY_MISSING_EVAL_SHARDS');result={'decision':decision,'checks':checks};a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(json.dumps(result,indent=2)+'\n');a.report.write_text('# R1 evaluation gate\n\nDecision: `'+decision+'`\n\n'+json.dumps(checks,indent=2)+'\n');print(json.dumps(result,indent=2));return 0 if decision.endswith('COMPLETE') else 2
if __name__=='__main__':raise SystemExit(main())
